import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const UserDashboard = () => {
  // Initialize with a default "loading" state for 1 slot
  const [singleSlot, setSingleSlot] = useState(null);

  useEffect(() => {
    fetchSlot();
    const interval = setInterval(fetchSlot, 2000); 
    return () => clearInterval(interval);
  }, []);

  async function fetchSlot() {
    // Fetch only the first slot (limit(1))
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("slot", { ascending: true })
      .limit(1);

    if (error) console.log("Error:", error);
    if (data && data.length > 0) {
      setSingleSlot(data[0]);
    }
  }

  // Calculate simple stats based on that one slot
  const isOccupied = singleSlot?.status === "occupied";
  const availableCount = isOccupied ? 0 : 1;
  const occupiedCount = isOccupied ? 1 : 0;

  return (
    <main className="dashboard-root">
      
      {/* 1. STATS (Simplified for 1 slot) */}
      <section className="stats-container">
        <div className="stat-card green">
          <div className="stat-title">Available</div>
          <div className="stat-value">{availableCount}</div>
        </div>

        <div className="stat-card red">
          <div className="stat-title">Occupied</div>
          <div className="stat-value">{occupiedCount}</div>
        </div>
      </section>

      {/* 2. SINGLE SLOT LAYOUT */}
      <section className="layout-section">
        <div className="layout-header">Live Parking Spot Status</div>
        
        {/* We use a new class 'single-slot-container' to center it */}
        <div className="single-slot-container">
          {!singleSlot ? (
            <p style={{color:'white'}}>Loading...</p>
          ) : (
            <SlotCard slot={singleSlot} />
          )}
        </div>
      </section>

    </main>
  );
};

export default UserDashboard;
